import { useState } from "react"

interface Inputs {
    pageCount: number
}

export default function usePagination({ pageCount }: Inputs) {
    const [pageIndex, setPageIndexState] = useState(0)
    const count = Math.max(0, Math.floor(pageCount))
    const lastIndex = Math.max(0, count - 1)
    const selectedIndex = Math.min(pageIndex, lastIndex)

    const setPageIndex = ({ index }: { index: number }) => {
        setPageIndexState(Math.max(0, Math.min(Math.round(index), lastIndex)))
    }

    const pages = Array.from({ length: count }, (_, index) => ({
        selected: index === selectedIndex,
        select: () => setPageIndex({ index }),
    }))

    return { setPageIndex, pages }
}

addPropertyControls(
    usePagination,
    {
        pageCount: {
            type: ControlType.Number,
            defaultValue: 3,
            min: 1,
            step: 1,
            displayStepper: true,
        },
    },
    {
        setPageIndex: {
            type: ControlType.EventHandler,
            parameters: [
                {
                    type: ControlType.Object,
                    controls: {
                        index: { type: ControlType.Number, title: "Index" },
                    },
                },
            ],
        },
        pages: {
            type: ControlType.Array,
            control: {
                type: ControlType.Object,
                controls: {
                    selected: { type: ControlType.Boolean },
                    select: { type: ControlType.EventHandler },
                },
            },
        },
    }
)
